/**
 * Point toward the target along the track axis, while locking the other axis
 *
 * bpy.types.LockedTrackConstraint
 */
export interface LockedTrackConstraint extends R.Constraint {
  /** Target along length of bone: Head is 0, Tail is 1 Range: 0 to 1. Default: 0.0. */
  get head_tail(): H.Ref<number>;
  set head_tail(v: H.In<number>);
  /** Follow shape of B-Bone segments when calculating Head/Tail position Default: False. */
  get use_bbone_shape(): H.Ref<boolean>;
  set use_bbone_shape(v: H.In<boolean>);
  /** Target object */
  get target(): H.Ptr<R.Object>;
  set target(v: R.Object | null);
  /** Armature bone, mesh or lattice vertex group, ... Default: "". */
  get subtarget(): H.Ref<string>;
  set subtarget(v: H.In<string>);
  /**
   * Axis that points to the target object Default: 'TRACK_X'.
   * - `TRACK_X`: X
   * - `TRACK_Y`: Y
   * - `TRACK_Z`: Z
   * - `TRACK_NEGATIVE_X`: -X
   * - `TRACK_NEGATIVE_Y`: -Y
   * - `TRACK_NEGATIVE_Z`: -Z
   */
  get track_axis(): H.Ref<"TRACK_X" | "TRACK_Y" | "TRACK_Z" | "TRACK_NEGATIVE_X" | "TRACK_NEGATIVE_Y" | "TRACK_NEGATIVE_Z">;
  set track_axis(v: H.In<"TRACK_X" | "TRACK_Y" | "TRACK_Z" | "TRACK_NEGATIVE_X" | "TRACK_NEGATIVE_Y" | "TRACK_NEGATIVE_Z">);
  /**
   * Axis that points upward Default: 'LOCK_X'.
   * - `LOCK_X`: X
   * - `LOCK_Y`: Y
   * - `LOCK_Z`: Z
   */
  get lock_axis(): H.Ref<"LOCK_X" | "LOCK_Y" | "LOCK_Z">;
  set lock_axis(v: H.In<"LOCK_X" | "LOCK_Y" | "LOCK_Z">);
}

